NEWF = json.loads(r"""{"inc/api/dejavoo.php": "<?php\n/* (2.99.638b - LENH-638 A) Settings -> Payments -> \"Dejavoo P5 (NailFlow)\": the card terminal of this salon \u2013 NailFlow only (American Nails' owner = NailFlow,\n   or a NailFlow support session at another salon). The owner of another salon is refused by nf_only_guard (NF_ONLY_ACTS, luat AN/MO 636 group 3).\n   The Register ID / Auth Key are never sent back (only \"\u2026abcd\"); typed once, kept encrypted (inc/dejavoo.php). Sandbox unless dv_env = live (not here). */\ndeclare(strict_types=1);\nif (!defined('API_MAIN')) { http_response_code(404); exit; }\nrequire_once APP_ROOT . '/inc/dejavoo.php';\nneed_admin();\nif (function_exists('nf_only') && nf_only()) fail(nf_only_say(), 403); // (also refused by need_admin's guard \u2013 twice is fine)\n$dvLog = function (): array { $l = json_decode((string)setting('dv_log'), true); return array_slice(array_reverse(is_array($l) ? $l : []), 0, 15); };\nswitch ($action) {\ncase 'dv_info':\n    json_out(['ok' => true, 'dv' => dv_shown() + ['ready' => dv_ready()], 'log' => $dvLog()]);\ncase 'dv_save':\n    if ($method !== 'POST') fail('POST only', 405);\n    $was = dv_shown();\n    try { dv_set_creds(array_key_exists('tpn', $in) ? (string)$in['tpn'] : '', array_key_exists('reg', $in) ? (string)$in['reg'] : '', array_key_exists('auth', $in) ? (string)$in['auth'] : ''); }\n    catch (InvalidArgumentException $e) { fail($e->getMessage()); }\n    if (!empty($in['clear'])) dv_set_creds(null, null, null);\n    if (array_key_exists('on', $in)) { if (!empty($in['on']) && !dv_ready()) fail('Type the TPN and the Auth Key first.'); set_setting('dv_on', !empty($in['on']) ? '1' : '0'); }\n    $now = dv_shown();\n    $ch = []; foreach (['tpn' => 'TPN', 'reg' => 'Register ID', 'auth' => 'Auth Key', 'on' => 'on'] as $k => $lab) if ($was[$k] !== $now[$k]) $ch[] = $lab;\n    if ($ch) audit('setting', 'Dejavoo P5', 'changed', implode(', ', $ch), 'Settings \u2192 Payments \u2192 Dejavoo P5'); // never the codes\n    json_out(['ok' => true, 'dv' => $now + ['ready' => dv_ready()], 'log' => $dvLog()]);\ncase 'dv_check': // \"Check the connection\" = Terminal Connection Status (nothing is charged)\n    if ($method !== 'POST') fail('POST only', 405);\n    $r = dv_terminal_status(); json_out(['ok' => true, 'online' => $r['online'], 'status' => $r['status'], 'msg' => $r['msg'], 'log' => $dvLog()]);\n}\nfail('Unknown action', 404);\n", "assets/admin/dejavoo-hq.js": "/* (2.99.638b - LENH-638 A) Settings -> Payments: one box at the END \"Dejavoo P5 (NailFlow)\" \u2013 the card terminal codes (TPN, Register ID, Auth Key),\n   \"Card on the P5\" on/off, \"Check the connection\", the last calls. ONLY for NailFlow: American Nails' owner or a NailFlow support session (S.support);\n   the owner of another salon never sees it (and the server refuses it). Nothing else on the page changes. Loaded with Settings (LAZY_FILES). */\n'use strict';\n(function () {\n  if (typeof SET_PAGES === 'undefined') return;\n  const vi = () => (typeof helpLang === 'function' ? !!helpLang() : true);\n  const T = (en, v) => (vi() ? v : en);\n  const mine = () => !IS_MGR && (!S.nfOnly || !!S.support);\n  const say = (b, t, bad) => { const p = b.querySelector('#dvMsg'); if (p) { p.textContent = t; p.style.color = bad ? 'var(--danger, #c0392b)' : ''; } };\n  const logRows = (l) => (l || []).slice(0, 8).map(x => `<li>${esc(x.at || '')} \u00b7 ${esc(x.op || '')}${x.amount != null ? ' $' + esc(x.amount) : ''} \u00b7 ${esc(x.status || '')}${x.last4 ? ' \u00b7 \u2022\u2022' + esc(x.last4) : ''}</li>`).join('');\n  async function box(b) {\n    if (!mine() || b.querySelector('#dvBox')) return;\n    const d = document.createElement('div'); d.className = 'card'; d.id = 'dvBox'; d.style.marginTop = '12px'; b.appendChild(d);\n    let j; try { j = await api('dv_info'); } catch (e) { d.remove(); return; }\n    const v = j.dv || {};\n    d.innerHTML = `<h3 style=\"margin-top:0\">\ud83d\udcb3 Dejavoo P5 <span class=\"muted\">(NailFlow)</span></h3>\n      <p class=\"hint\">${esc(T('Card terminal through SPIn Cloud. ' + (v.env === 'live' ? 'LIVE' : 'Sandbox (test) \u2013 no real money.'), 'M\u00e1y c\u00e0 th\u1ebb qua SPIn Cloud. ' + (v.env === 'live' ? 'LIVE (ti\u1ec1n th\u1eadt)' : 'Sandbox (th\u1eed) \u2013 kh\u00f4ng c\u00f3 ti\u1ec1n th\u1eadt.')))}</p>\n      <div class=\"field\"><label for=\"dvTpn\">TPN</label><input id=\"dvTpn\" inputmode=\"numeric\" autocomplete=\"off\" value=\"${esc(v.tpn || '')}\" placeholder=\"220926423654\"></div>\n      <div class=\"field\"><label for=\"dvReg\">Register ID</label><input id=\"dvReg\" type=\"password\" autocomplete=\"new-password\" value=\"\" placeholder=\"${esc(v.reg || T('not set', 'ch\u01b0a c\u00f3'))}\"></div>\n      <div class=\"field\"><label for=\"dvAuth\">Auth Key</label><input id=\"dvAuth\" type=\"password\" autocomplete=\"new-password\" value=\"\" placeholder=\"${esc(v.auth || T('not set', 'ch\u01b0a c\u00f3'))}\"></div>\n      <p class=\"hint\">${esc(T('Empty = keep the one saved. Never shown again.', '\u0110\u1ec3 tr\u1ed1ng = gi\u1eef m\u00e3 \u0111\u00e3 l\u01b0u. M\u00e3 kh\u00f4ng bao gi\u1edd hi\u1ec7n l\u1ea1i.'))}</p>\n      <label class=\"chk\"><input type=\"checkbox\" id=\"dvOn\" ${v.on ? 'checked' : ''}> ${esc(T('Card on the P5 at Checkout', 'C\u00e0 th\u1ebb tr\u00ean m\u00e1y P5 \u1edf Checkout'))}</label>\n      <div class=\"navbtns\" style=\"margin-top:10px\"><button type=\"button\" class=\"btn\" id=\"dvSave\">${esc(T('Save', 'L\u01b0u'))}</button> <button type=\"button\" class=\"btn\" id=\"dvCheck\">${esc(T('Check the connection', 'Ki\u1ec3m k\u1ebft n\u1ed1i'))}</button></div>\n      <p class=\"hint\" id=\"dvMsg\"></p><ul class=\"hint\" id=\"dvLog\" style=\"margin:6px 0 0;padding-left:18px\">${logRows(j.log)}</ul>`;\n    d.querySelector('#dvSave').onclick = async () => {\n      const body = { tpn: d.querySelector('#dvTpn').value.trim(), reg: d.querySelector('#dvReg').value.trim(), auth: d.querySelector('#dvAuth').value.trim(), on: d.querySelector('#dvOn').checked };\n      try { const r = await api('dv_save', body); d.querySelector('#dvReg').value = ''; d.querySelector('#dvAuth').value = '';\n        d.querySelector('#dvReg').placeholder = r.dv.reg || T('not set', 'ch\u01b0a c\u00f3'); d.querySelector('#dvAuth').placeholder = r.dv.auth || T('not set', 'ch\u01b0a c\u00f3');\n        d.querySelector('#dvLog').innerHTML = logRows(r.log); say(d, T('Saved.', '\u0110\u00e3 l\u01b0u.')); } catch (e) { say(d, e.message || String(e), true); }\n    };\n    d.querySelector('#dvCheck').onclick = async () => {\n      say(d, T('Checking\u2026', '\u0110ang ki\u1ec3m\u2026'));\n      try { const r = await api('dv_check', {}); d.querySelector('#dvLog').innerHTML = logRows(r.log);\n        say(d, r.online ? T('P5 connected (Online).', 'M\u00e1y P5 \u0111ang k\u1ebft n\u1ed1i (Online).') : T('P5 not connected: ', 'M\u00e1y P5 ch\u01b0a k\u1ebft n\u1ed1i: ') + (r.status || '') + (r.msg ? ' \u2013 ' + r.msg : ''), !r.online); } catch (e) { say(d, e.message || String(e), true); }\n    };\n  }\n  const wrap = (fn) => { if (typeof fn !== 'function' || fn.__dv) return fn;\n    const w = function (b) { const r = fn.apply(this, arguments); try { if (b) Promise.resolve(r).then(() => box(b)); } catch (e) {} return r; };\n    for (const x of Object.keys(fn)) w[x] = fn[x]; w.__dv = 1; return w; };\n  SET_PAGES.pay = wrap(SET_PAGES.pay);\n})();\n"}""")
